WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '02')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'SINGLE', 5000, CURRENT_DATE - 1, 'BusMap/DanaBus imported fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'SINGLE' AND f.effective_until IS NULL);
WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '02')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'MONTHLY', 100000, CURRENT_DATE - 1, 'UniBus demo monthly fare derived from BusMap single fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'MONTHLY' AND f.effective_until IS NULL);

