WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '03')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'SINGLE', 18000, CURRENT_DATE - 1, 'BusMap/DanaBus imported fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'SINGLE' AND f.effective_until IS NULL);
WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '03')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'MONTHLY', 200000, CURRENT_DATE - 1, 'UniBus demo monthly fare derived from BusMap single fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'MONTHLY' AND f.effective_until IS NULL);

INSERT INTO routes (route_name, route_code, description, distance_km, estimated_minutes, frequency_min, color_hex, is_circular, status, created_at, external_source, external_route_id, source_updated_at, is_interregional)
VALUES ('Cầu Trần Thị Lý - Hoà Tiến', '04', 'source=BUSMAP | operationTime=05:45 - 19:00 | outBound=45 Nguyễn Tất Thành (Cầu Thuận Phước) – Đường 3/2 – Đống Đa – Lý Tự Trọng – Nguyễn Thị Minh Khai – Hùng Vương – Phan Châu Trinh – Nguyễn Văn Linh – Nguyễn Tri Phương – Nguyễn Hữu Thọ – CMT8 – Cầu Cẩm Lệ – Quốc Lộ 1A – Phan Bội Châu – Phan Châu Trinh – 954 Phan Châu Trinh (Tam Kỳ). | inBound=954 Phan Châu Trinh (Tam Kỳ) – Phan Châu Trinh – Quốc Lộ 1A – Cầu Cẩm Lệ – CMT8 – Nguyễn Hữu Thọ – Nguyễn Tri Phương – Nguyễn Văn Linh – Hoàng Diệu – Thá', NULL, NULL, 15, '#144fcc', FALSE, 'ACTIVE', CURRENT_TIMESTAMP, 'BUSMAP_DN', '4', CURRENT_TIMESTAMP, FALSE)
