WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '04')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'SINGLE', 28000, CURRENT_DATE - 1, 'BusMap/DanaBus imported fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'SINGLE' AND f.effective_until IS NULL);
WITH route_data AS (SELECT route_id FROM routes WHERE route_code = '04')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'MONTHLY', 280000, CURRENT_DATE - 1, 'UniBus demo monthly fare derived from BusMap single fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'MONTHLY' AND f.effective_until IS NULL);

INSERT INTO routes (route_name, route_code, description, distance_km, estimated_minutes, frequency_min, color_hex, is_circular, status, created_at, external_source, external_route_id, source_updated_at, is_interregional)
VALUES ('Chung cư Hoà Hiệp Nam-Công viên Biển Đông', '05', 'source=BUSMAP | operationTime=05:30 - 19:00 | outBound=Nguyễn Tất Thành (Khu chung cư Hòa Hiệp Nam) - Trần Đình Tri - Kinh Dương Vương - Phùng Hưng - Hoàng Thị Loan - Lý Thái Tông - Dũng Sĩ Thanh Khê - Trần Cao Vân - Quang Trung - Trần Phú - Cầu Rồng - đường dẫn xuống Cầu Rồng - Trần Hưng Đạo - Nguyễn Công Trứ - Hồ Nghinh - Võ Văn Kiệt - Võ Nguyên Giáp - CV Biển Đông | inBound=CV Biển Đông - Võ Nguyên Giáp - Võ Văn Kiệt - Hồ Nghinh - Nguyễn Công Trứ - Trần Hưng Đạo đường dẫn lên Cầu Rồng - Cầu R', NULL, NULL, 20, '#144fcc', FALSE, 'ACTIVE', CURRENT_TIMESTAMP, 'BUSMAP_DN', '1301', CURRENT_TIMESTAMP, FALSE)
