SELECT route_data.route_id, stop_data.stop_id, 20, 3, 1, '108.2336091,16.0612812 108.2336146,16.0612814 108.2336127,16.0612887 108.2338595,16.0613119 108.2339855,16.0613171 108.2341974,16.0613094 108.2342940,16.0612552 108.2343610,16.0612475 108.2344308,16.0612681 108.2344817,16.0612965 108.2345354,16.0613454 108.2364612,16.0616496 108.2374107,16.0618197 108.2385051,16.0619872 108.2393044,16.0621367 108.2392993,16.0621444 108.2398841,16.0622527 108.2399967,16.0622063 108.2400933,16.0621857 108.2401845,16.0622166 108.2402649,16.0622578 108.2403239,16.0623455 108.2427755,16.0630156 108.2427808,16.0630156 108.2427778,16.0630340 108.2434134,16.0632222 108.2435368,16.0633098 108.2450040,16.0637274 108.2454144,16.0638099 108.2454975,16.0637738 108.2456209,16.0637815 108.2457067,16.0638073 108.2457979,16.0638923 108.2458328,16.0639774 108.2458248,16.0640934 108.2457550,16.0641913 108.2456477,16.0642480 108.2455673,16.0644929 108.2455190,16.0648202 108.2455136,16.0653306 108.2456102,16.0654285 108.2456531,16.0655703 108.2456464,16.0657763'
FROM route_data CROSS JOIN stop_data
ON CONFLICT (route_id, station_direction, stop_order) DO UPDATE SET
    stop_id = EXCLUDED.stop_id,
    minutes_from_previous_stop = EXCLUDED.minutes_from_previous_stop,
    path_points = EXCLUDED.path_points;

WITH route_data AS (SELECT route_id FROM routes WHERE route_code = 'TMF1')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'SINGLE', 5000, CURRENT_DATE - 1, 'BusMap/DanaBus imported fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'SINGLE' AND f.effective_until IS NULL);
WITH route_data AS (SELECT route_id FROM routes WHERE route_code = 'TMF1')
INSERT INTO fares (route_id, fare_type, amount, effective_from, notes)
SELECT route_id, 'MONTHLY', 100000, CURRENT_DATE - 1, 'UniBus demo monthly fare derived from BusMap single fare' FROM route_data
WHERE NOT EXISTS (SELECT 1 FROM fares f WHERE f.route_id = route_data.route_id AND f.fare_type = 'MONTHLY' AND f.effective_until IS NULL);

-- Demo university can buy passes for university-oriented public routes.
WITH university_data AS (SELECT university_id FROM universities WHERE code = 'UNIBUS_DEMO_FLOW'),
linked_routes AS (SELECT route_id FROM routes WHERE route_code IN ('02', '16', 'R16'))
INSERT INTO route_universities (route_id, university_id, active_from, status, created_at, updated_at)
SELECT linked_routes.route_id, university_data.university_id, CURRENT_DATE - 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM linked_routes CROSS JOIN university_data
WHERE NOT EXISTS (
    SELECT 1 FROM route_universities ru
    WHERE ru.route_id = linked_routes.route_id
      AND ru.university_id = university_data.university_id
      AND ru.status = 'ACTIVE'
);

COMMIT;
